<section class="step-panel hidden rounded-3xl border border-white/10 bg-panel p-5 sm:p-8" data-step="3"><h2 class="text-xl font-black">04 · Periksa & konfirmasi</h2><p class="mt-1 text-sm text-zinc-400">Pastikan semua informasi sudah benar sebelum booking dibuat.</p><dl class="mt-5 grid gap-3 sm:grid-cols-2" id="reviewSummary"></dl><div class="mt-5 flex items-center justify-between rounded-2xl bg-black/25 p-5"><div><p class="text-sm text-zinc-400">Estimasi biaya awal</p><p class="mt-1 text-2xl font-black text-brand" id="reviewPrice">Rp 0</p></div><span class="rounded-full border border-brand/30 px-3 py-1 text-xs text-brand">Motofix</span></div><p class="mt-4 text-xs leading-5 text-zinc-500">Dengan mengirim booking, kamu menyetujui bahwa jadwal dapat dikonfirmasi ulang oleh tim bengkel. Estimasi biaya dapat berubah jika ditemukan komponen tambahan.</p></section>
<div class="mt-5 flex flex-wrap justify-between gap-3"><button type="button" id="backBtn" class="hidden rounded-xl border border-white/15 px-5 py-3 text-sm font-bold hover:border-brand">← Kembali</button><div class="ml-auto flex gap-3"><a href="{{ route('dashboard') }}" class="rounded-xl border border-white/15 px-5 py-3 text-sm">Batal</a><button type="button" id="nextBtn" class="rounded-xl bg-brand px-6 py-3 text-sm font-black text-black transition hover:-translate-y-0.5 hover:bg-orange-400">Lanjut →</button><button type="submit" id="submitBtn" class="hidden rounded-xl bg-brand px-6 py-3 text-sm font-black text-black transition hover:-translate-y-0.5 hover:bg-orange-400">Konfirmasi booking ✓</button></div></div></form></main>
<script>
const panels=[...document.querySelectorAll('[data-step]')];let current=0;
function showStep(n){current=n;panels.forEach((p,i)=>p.classList.toggle('hidden',i!==n));for(let i=0;i<4;i++){document.getElementById('progress-'+i).className='h-1.5 rounded-full '+(i<=n?'bg-brand':'bg-white/10');document.getElementById('progress-label-'+i).className='mt-2 text-[10px] sm:text-xs '+(i<=n?'text-brand':'text-zinc-500')}document.getElementById('backBtn').classList.toggle('hidden',n===0);document.getElementById('nextBtn').classList.toggle('hidden',n===3);document.getElementById('submitBtn').classList.toggle('hidden',n!==3);if(n===3)buildReview();window.scrollTo({top:0,behavior:'smooth'})}
function validStep(){let ok=true;panels[current].querySelectorAll('input,textarea,select').forEach(el=>{if(!el.checkValidity()){el.reportValidity();ok=false;}});return ok}
function val(name){const el=document.querySelector(`[name="${name}"]:checked`)||document.querySelector(`[name="${name}"]`);return el?el.value:'-'}
function buildReview(){const service=document.querySelector('[name="service_id"]:checked');const data=[['Paket servis',service?.dataset.name||'-'],['Keluhan',val('keluhan')],['Motor',val('merek_motor')+' '+val('tipe_motor')],['Nomor polisi',val('nomor_plat')],['Tanggal',val('tanggal')],['Jam',val('jam')],['Mekanik',val('mekanik_name')],['Pembayaran',val('payment_method').replace('_',' ').toUpperCase()]];document.getElementById('reviewSummary').innerHTML=data.map(([k,v])=>`<div class="rounded-xl border border-white/10 bg-black/20 p-3"><dt class="text-xs text-zinc-500">${k}</dt><dd class="mt-1 break-words text-sm font-semibold"></dd></div>`).join('');[...document.querySelectorAll('#reviewSummary dd')].forEach((el,i)=>el.textContent=data[i][1]);document.getElementById('reviewPrice').textContent='Rp '+new Intl.NumberFormat('id-ID').format(Number(service?.dataset.price||0))}
document.getElementById('nextBtn').addEventListener('click',()=>{if(!validStep())return;if(current<3)showStep(current+1)});document.getElementById('backBtn').addEventListener('click',()=>showStep(Math.max(0,current-1)));document.getElementById('bookingWizard').addEventListener('submit',e=>{for(let i=0;i<3;i++){let bad=[...panels[i].querySelectorAll('input,textarea,select')].find(el=>!el.checkValidity());if(bad){e.preventDefault();showStep(i);bad.reportValidity();return}}});
document.querySelectorAll('[name="service_id"]').forEach(el=>el.addEventListener('change',()=>document.querySelectorAll('.service-option').forEach(card=>card.classList.toggle('border-brand',card.querySelector('input').checked))));
</script></body></html>
